//Based on a #mathchallange from Annie Perkins
//https://twitter.com/anniek_p/status/1244220881347502080

var SIZE = 20;
var lineWeight = SIZE/3;
var row = [];
var column = [];
var points = [];
var mouseXIndex, mouseYIndex;

function setup() {
	createCanvas(windowWidth, windowHeight);
	strokeWeight(lineWeight);
	textSize(SIZE);

	for(let y = 0; y < height; y += (Math.max(0.001, Math.abs(SIZE)) || 1))
		row.push(random([0, 1]));

	for(let x = 0; x < width; x += (Math.max(0.001, Math.abs(SIZE)) || 1))
		column.push(random([0, 1]));
}

function draw() {
	background(255);
	mouseXIndex = constrain(round(((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))-SIZE*1.5)/SIZE), 0, column.length);
	mouseYIndex = constrain(round(((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))-SIZE*1.5)/SIZE), 0, row.length);

	column.forEach((value, index) => {
		if(random() < 0.01) column[index] = value == 1 ? 0 : 1;
		noStroke();
		text(value, index * SIZE + SIZE + SIZE/4, SIZE);
		if(index == mouseXIndex) stroke(100);
		else stroke(0);
		for(let i = 1; i < row.length; i++)
			if(i % 2 == value)
				myline(index * SIZE + SIZE + SIZE / 2,
							 i * SIZE + SIZE / 2,
							 index * SIZE + SIZE + SIZE / 2,
							 i * SIZE + SIZE + SIZE / 2);
	});

	row.forEach((value, index) => {
		if(random() < 0.01) row[index] = value == 1 ? 0 : 1;
		noStroke();
		text(value, SIZE/2, index * SIZE + SIZE + SIZE*3/4);
		if(index == mouseYIndex) stroke(100);
		else stroke(0);
		for(let i = 1; i < column.length; i++)
			if(i % 2 == value)
				myline(SIZE / 2 + i * SIZE,
							 index * SIZE + SIZE + SIZE / 2,
							 SIZE / 2 + i * SIZE + SIZE,
							 index * SIZE + SIZE + SIZE / 2);
	});
}

function mousePressed(){
	column[mouseXIndex] = column[mouseXIndex] == 1 ? 0 : 1;
	row[mouseYIndex] = row[mouseYIndex] == 1 ? 0 : 1;
}

function myline(x1, y1, x2, y2){
	let m = millis()/1000;
	let nx1 = noise(y1/100 + m) * SIZE * 3;
	let ny1 = noise(x1/100 + m) * SIZE * 3;
	let nx2 = noise(y2/100 + m) * SIZE * 3;
	let ny2 = noise(x2/100 + m) * SIZE * 3;
	line(x1 + nx1, y1 + ny1, x2 + nx2, y2 + ny2);
}
